package app.noir.mobile;

import android.app.job.*;
import android.content.*;
import android.net.*;
import android.os.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.util.*;

public final class PhoneReadyJob extends JobService {
 public static final int JOB_ID=708,REFILL_ID=709;
 static final java.util.concurrent.Semaphore RUN=new java.util.concurrent.Semaphore(1);volatile boolean ownsRun;
 volatile boolean stopped;Thread worker;DownloadStore captured;
 static PhoneReady policy(DataStore data){return PhoneReady.at(data.context.getFilesDir());}
 static List<JSONObject> plan(DataStore data){PhoneReady p=policy(data);List<JSONObject> base=DataStore.objects(data.itemsShared());JSONObject shows=p.effectiveShows(base);List<JSONObject> items=PhoneReady.mergeSchedules(base,shows,data.settings().optJSONObject("schedules"));return PhoneReady.select(items,shows,data.now(),p.ahead());}
 public static JobInfo jobInfo(Context c){return jobInfo(c,null);}
 /* Network and charging come from the settings (null: today's defaults, unmetered Wi-Fi and charging). */
 public static JobInfo jobInfo(Context c,PhoneReady p){return new JobInfo.Builder(JOB_ID,new ComponentName(c,PhoneReadyJob.class)).setRequiredNetworkType(p==null||p.wifiOnly()?JobInfo.NETWORK_TYPE_UNMETERED:JobInfo.NETWORK_TYPE_ANY).setRequiresCharging(p==null||p.needCharging()).setPeriodic(6*3600000L).setPersisted(true).build();}
 public static void schedule(Context c){try{DataStore data=NoirApp.data;if(data==null)return;JobScheduler scheduler=c.getSystemService(JobScheduler.class);if(policy(data).enabled()){JobInfo want=jobInfo(c,policy(data)),have=scheduler.getPendingJob(JOB_ID);if(have==null||have.getNetworkType()!=want.getNetworkType()||have.isRequireCharging()!=want.isRequireCharging())scheduler.schedule(want);}else {scheduler.cancel(JOB_ID);scheduler.cancel(REFILL_ID);}}catch(RuntimeException ignored){/* Manager installs the manifest entry. */}}
 /* Settings changed: drop the waiting refill job so it is rebuilt with the new window, network and charging choices. */
 public static void reschedule(Context c){try{c.getSystemService(JobScheduler.class).cancel(REFILL_ID);}catch(RuntimeException ignored){}refill(c);}
 public static void refill(Context c){schedule(c);DataStore data=NoirApp.data;if(data==null||!policy(data).enabled())return;PhoneReady p=policy(data);data.images.execute(()->p.planned(plan(data)));try{JobScheduler jobs=c.getSystemService(JobScheduler.class);if(jobs.getPendingJob(REFILL_ID)!=null)return;long delay=windowDelay(clock.get(),p.winStart(),p.winEnd());jobs.schedule(new JobInfo.Builder(REFILL_ID,new ComponentName(c,PhoneReadyJob.class)).setRequiredNetworkType(p.wifiOnly()?JobInfo.NETWORK_TYPE_UNMETERED:JobInfo.NETWORK_TYPE_ANY).setRequiresCharging(p.needCharging()).setMinimumLatency(delay).setPersisted(true).build());}catch(RuntimeException ignored){}}
 /* Test seam: the clock the window is read from. */
 static java.util.function.Supplier<Calendar> clock=Calendar::getInstance;
 /* Milliseconds until the window next opens (0 when it is open now). */
 static long windowDelay(Calendar now,int start,int end){if(PhoneReady.inWindow(now.get(Calendar.HOUR_OF_DAY),start,end))return 0;Calendar next=(Calendar)now.clone();next.set(Calendar.HOUR_OF_DAY,start);next.set(Calendar.MINUTE,0);next.set(Calendar.SECOND,0);next.set(Calendar.MILLISECOND,0);if(!next.after(now))next.add(Calendar.DAY_OF_YEAR,1);return next.getTimeInMillis()-now.getTimeInMillis();}
 static String hours(int h){return String.format(Locale.ROOT,"%02d:00",h);}
 /* Block text shown to the user: the default window keeps its old wording; other windows name their hours. */
 static String say(String block){String prefix="Waiting for your download window (";if(block.startsWith(prefix)&&block.endsWith(")"))return Loc.f(prefix+"%s)",block.substring(prefix.length(),block.length()-1));return Loc.t(block);}
 static String conditions(Context c){DataStore data=NoirApp.data;return conditions(c,data==null?new PhoneReady(c.getFilesDir()):policy(data));}
 static String conditions(Context c,PhoneReady p){if(!PhoneReady.inWindow(clock.get().get(Calendar.HOUR_OF_DAY),p.winStart(),p.winEnd()))return p.winStart()==0&&p.winEnd()==6?"Waiting for overnight hours (00:00\u201306:00)":"Waiting for your download window ("+hours(p.winStart())+"\u2013"+hours(p.winEnd())+")";if(p.needCharging()){BatteryManager battery=c.getSystemService(BatteryManager.class);if(battery==null||!battery.isCharging())return "Waiting for charging";}ConnectivityManager cm=c.getSystemService(ConnectivityManager.class);NetworkCapabilities nc=cm==null?null:cm.getNetworkCapabilities(cm.getActiveNetwork());if(p.wifiOnly()){if(nc==null||!nc.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)||!nc.hasCapability(NetworkCapabilities.NET_CAPABILITY_NOT_METERED)||!nc.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET))return "Waiting for unmetered Wi-Fi";}else if(nc==null||!nc.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET))return "Waiting for a network connection";return "";}
 static String allowed(DataStore data,DownloadStore store){PhoneReady p=policy(data);if(data!=NoirApp.data||store!=NoirApp.downloads)return "Phone profile changed";if(!p.enabled())return "Keep ready is off";if(p.paused())return "Keep ready paused";return conditions(data.context,p);}
 @Override public boolean onStartJob(JobParameters parameters){if(worker!=null&&worker.isAlive())return false;stopped=false;DataStore data=NoirApp.data;captured=NoirApp.downloads;worker=new Thread(()->{try{if(RUN.tryAcquire()){ownsRun=true;try{run(data,captured);}finally{ownsRun=false;RUN.release();}}}catch(Exception e){try{policy(data).log("","Keep ready interrupted; retrying later");}catch(RuntimeException saving){/* Stopped while saving: the next run starts clean. */}}finally{jobFinished(parameters,false);}},"Noir-keep-ready");worker.start();return true;}
 @Override public boolean onStopJob(JobParameters parameters){stopped=true;if(ownsRun&&captured!=null){JSONObject j=captured.job(captured.activeId);if(j!=null&&j.optBoolean("readyManaged"))captured.pause(j.optString("id"));}if(worker!=null)worker.interrupt();return true;}
 void run(DataStore data,DownloadStore store)throws Exception{PhoneReady p=policy(data);String reason=allowed(data,store);if(!reason.isEmpty()){p.blocked(reason);return;}cleanup(data,store,p,()->!stopped&&allowed(data,store).isEmpty());List<JSONObject> plan=plan(data);p.planned(plan);p.blocked("");
  for(JSONObject item:plan){if(stopped)return;if(!store.activeId.isEmpty()){p.blocked("Waiting for phone downloads to finish");return;}reason=allowed(data,store);if(!reason.isEmpty()){p.blocked(reason);return;}String id=item.optString("id");JSONObject old=store.job(id);if(!data.localFile(id).isEmpty()||old!=null&&(!old.optBoolean("readyManaged")||old.optBoolean("readyPickup")||old.optString("status").equals("complete")))continue;if(!p.canRetry(id,System.currentTimeMillis()))continue;
   try{
    boolean copied=false;if(data.paired()&&lan(data.address())){try{long size=pcSize(data,id);reason=storage(store,p,id,size);if(!reason.isEmpty()){p.blocked(reason);return;}if(store.enqueueReady(item,null,size)){p.log(id,"Copying from your PC over LAN");store.transferReady(id,j->{},()->!stopped&&allowed(data,store).isEmpty()&&p.wanted(item.optString("group")));copied=store.job(id).optString("status").equals("complete");}}catch(Exception e){p.log(id,"PC copy unavailable; checking phone sources");}}
    if(copied){p.log(id,"Ready to watch offline");continue;}if(stopped||!allowed(data,store).isEmpty())return;
    if(old!=null){store.queueReady(id);store.transferReady(id,j->{},()->!stopped&&allowed(data,store).isEmpty()&&p.wanted(item.optString("group")));if(store.job(id).optString("status").equals("complete")){p.log(id,"Ready to watch offline");continue;}if(!allowed(data,store).isEmpty())return;}
    PhoneDownloadProvider provider=store.providers.apply(new PhoneDownloadSettings(data.context).load());List<JSONObject> candidates=readySources(provider,item);JSONObject chosen=null;String storageBlock="";for(JSONObject c:candidates){reason=storage(store,p,id,c.optLong("size"));if(reason.isEmpty()){chosen=c;break;}storageBlock=reason;}
    if(chosen==null){if(!storageBlock.isEmpty()){p.blocked(storageBlock);return;}p.log(id,"Waiting for a confirmed cached single-episode source");p.retry(id,System.currentTimeMillis());continue;}
    if(store.enqueueReady(item,chosen,chosen.optLong("size"))){p.log(id,"Downloading a cached source on this phone");store.transferReady(id,j->{},()->!stopped&&allowed(data,store).isEmpty()&&p.wanted(item.optString("group")));JSONObject result=store.job(id);if(result.optString("status").equals("complete"))p.log(id,"Ready to watch offline");else{p.log(id,"Keep ready interrupted; retrying later");p.retry(id,System.currentTimeMillis());}}
   }catch(Exception e){p.log(id,"Ready source unavailable; retrying later");p.retry(id,System.currentTimeMillis());}
  }
 }
 static List<JSONObject> readySources(PhoneDownloadProvider provider,JSONObject item)throws Exception{List<JSONObject> safe=new ArrayList<>();for(JSONObject c:provider.search(item))if(c.optBoolean("cached")&&!c.optBoolean("pack")&&c.optString("service").equals("direct")&&c.optLong("size")>0)safe.add(c);return PhoneDownloadProvider.ranked(safe,provider.config,"");}
 static boolean lan(String address){try{String host=new URI(address.contains("://")?address:"https://"+address).getHost();if(host==null)return false;for(InetAddress a:InetAddress.getAllByName(host))if(a.isSiteLocalAddress()||a.isLinkLocalAddress())return true;}catch(Exception ignored){}return false;}
 static long pcSize(DataStore data,String id)throws Exception{HttpURLConnection c=data.media(id,"bytes=0-0");try{c.setConnectTimeout(10000);c.setReadTimeout(10000);int status=c.getResponseCode();if(status==404||status==410)throw new FileNotFoundException();long size=status==206?DownloadStore.range(c.getHeaderField("Content-Range"))[2]:status==200?c.getContentLengthLong():0;if(size<=0)throw new IOException();return size;}finally{c.disconnect();}}
 // Counts every storage place a profile can keep videos in (phone, SD card, moved jobs), each folder once.
 static long used(DownloadStore store){long total=0;ProfileStore profiles=new ProfileStore(store.context);Set<String> seen=new HashSet<>();for(JSONObject profile:DataStore.objects(profiles.list())){String id=profile.optString("id");List<File> dirs;try{dirs=profiles.downloadDirectories(id);}catch(RuntimeException e){Context c=ProfileStore.context(store.context,id);File base=c.getExternalFilesDir(null);dirs=Collections.singletonList(new File(base==null?c.getFilesDir():base,"offline"));}for(File dir:dirs){String key;try{key=dir.getCanonicalPath();}catch(java.io.IOException e){key=dir.getAbsolutePath();}if(!seen.add(key))continue;File[] files=dir.listFiles();if(files!=null)for(File f:files)if(ProfileStore.downloadFile(f))total=PhoneReady.add(total,f.length());}}return total;}
 static String storage(DownloadStore store,PhoneReady p,String id,long total){try{JSONArray jobs=store.diskJobs();return PhoneReady.storageReason(used(store),PhoneReady.reserved(jobs,id),total<=0?-1:Math.max(0,total-store.safeLength(id)),p.budget(),new StatFs(store.targetDirectory(id).getAbsolutePath()).getAvailableBytes());}catch(Exception e){return "Storage is unavailable. Reinsert the SD card and try again.";}}
 static String episodeKey(JSONObject i){return (!i.optString("imdb").isEmpty()?i.optString("imdb"):i.optString("group",i.optString("id")))+":"+i.optInt("season")+":"+i.optInt("episode");}
 static List<Map<String,Boolean>> otherProgress(DataStore data){List<Map<String,Boolean>> result=new ArrayList<>();try{for(JSONObject profile:DataStore.objects(data.profiles.list())){String id=profile.optString("id");if(id.equals(data.profileId))continue;Map<String,Boolean> done=new HashMap<>();for(JSONObject i:DataStore.objects(NoirApp.dataFor(data.context,id).itemsShared())){String key=episodeKey(i);done.put(key,done.getOrDefault(key,true)&&PhoneReady.watched(i));}result.add(done);}}catch(Exception e){result.add(Collections.emptyMap());}return result;}
 static boolean otherUnfinished(JSONObject item,List<Map<String,Boolean>> profiles){if(item==null)return true;String key=episodeKey(item);for(Map<String,Boolean> profile:profiles)if(!profile.getOrDefault(key,false))return true;return false;}
 static boolean eligible(PhoneReady p,DownloadStore store,JSONObject j,JSONObject item,List<Map<String,Boolean>> other,Set<String> shield){String id=j.optString("id");return !p.ruleFor(item==null?"":item.optString("group")).equals("never")&&!shield.contains(id)&&store.ownsReadyFile(j)&&PhoneReady.cleanupEligible(j,item,true,otherUnfinished(item,other),p.protectedFile(id),p.removeScope().equals("all"),p.removeMovies());}
 /* Schedules (or re-dates, after a rule change) the removals without deleting anything. */
 public static void retarget(DataStore data,DownloadStore store){PhoneReady p=policy(data);List<JSONObject> list=DataStore.objects(data.itemsShared());Map<String,JSONObject> items=new HashMap<>();for(JSONObject i:list)items.put(i.optString("id"),i);scheduleRemovals(data,store,p,items,PhoneReady.shielded(list,p.keepWatched()),otherProgress(data),System.currentTimeMillis());}
 static void scheduleRemovals(DataStore data,DownloadStore store,PhoneReady p,Map<String,JSONObject> items,Set<String> shield,List<Map<String,Boolean>> other,long now){for(JSONObject j:DataStore.objects(store.jobs())){String id=j.optString("id");JSONObject item=items.get(id);String group=item==null?"":item.optString("group");boolean ruled=!p.ruleFor(group).equals("never");if(ruled&&j.optBoolean("readyManaged")&&j.optString("status").equals("complete")&&!store.ownsReadyFile(j)){p.protect(id,false);p.log(id,"File changed; removal cancelled");continue;}if(eligible(p,store,j,item,other,shield)){long at=PhoneReady.watchedAt(item);if(at>0)p.scheduleRemoval(id,group,at,now);else p.forgetRemoval(id);}else p.forgetRemoval(id);}}
 static void cleanup(DataStore data,DownloadStore store,PhoneReady p,java.util.function.BooleanSupplier permitted)throws Exception{List<JSONObject> list=DataStore.objects(data.itemsShared());Map<String,JSONObject> items=new HashMap<>();for(JSONObject i:list)items.put(i.optString("id"),i);Set<String> shield=PhoneReady.shielded(list,p.keepWatched());Map<String,JSONObject> jobs=new HashMap<>();for(JSONObject j:DataStore.objects(store.jobs()))jobs.put(j.optString("id"),j);List<Map<String,Boolean>> other=otherProgress(data);long now=System.currentTimeMillis();scheduleRemovals(data,store,p,items,shield,other,now);
  for(JSONObject r:DataStore.objects(p.removals())){if(!permitted.getAsBoolean())return;String id=r.optString("id");JSONObject j=jobs.get(id),item=items.get(id);long wait=PhoneReady.delayOf(r.optString("rule","d7"));if(j!=null&&wait>=0&&eligible(p,store,j,item,other,shield)&&r.optLong("at")<=now&&PhoneReady.watchedAt(item)>0&&PhoneReady.watchedAt(item)+wait<=now){synchronized(store){synchronized(data){synchronized(p){JSONObject fresh=data.item(id),freshJob=store.job(id);if(!permitted.getAsBoolean()||freshJob==null||!eligible(p,store,freshJob,fresh,other,shield)||PhoneReady.watchedAt(fresh)<=0||PhoneReady.watchedAt(fresh)+wait>now)continue;boolean managed=freshJob.optBoolean("readyManaged");store.remove(id);p.forgetRemoval(id);p.log(id,managed?"Removed watched Ready copy":"Removed watched download");}}}}}
 }
}
